import{_ as t,o,c as r,ag as e}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"加密和签名：概念与实际应用","description":"","frontmatter":{"title":"加密和签名：概念与实际应用","tags":["linux","ssl"],"categories":["linux"],"date":"2024/01/29"},"headers":[],"relativePath":"linux/croptyo.md","filePath":"linux/croptyo.md","lastUpdated":1784519165000}'),l={name:"linux/croptyo.md"};function s(i,a,n,p,d,c){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="加密和签名" tabindex="-1">加密和签名 <a class="header-anchor" href="#加密和签名" aria-label="Permalink to &quot;加密和签名&quot;">​</a></h1><h2 id="加密-vs-签名" tabindex="-1">加密 vs 签名 <a class="header-anchor" href="#加密-vs-签名" aria-label="Permalink to &quot;加密 vs 签名&quot;">​</a></h2><p>经常有人把加密和签名搞混，其实它们解决的是完全不同的问题。</p><p><strong>加密</strong>解决的是&quot;别人看不了&quot;——数据从 A 传到 B，中间被截获了也读不出内容。</p><p><strong>签名</strong>解决的是&quot;没被篡改过&quot;——收到一段数据，怎么确认它真的是对方发的、中间没被改过？</p><p>简单说：加密保护机密性，签名保护完整性。</p><h2 id="对称加密-vs-非对称加密" tabindex="-1">对称加密 vs 非对称加密 <a class="header-anchor" href="#对称加密-vs-非对称加密" aria-label="Permalink to &quot;对称加密 vs 非对称加密&quot;">​</a></h2><p><strong>对称加密</strong>：加解密用同一个密钥。快，但密钥怎么安全地给对方是个问题。</p><p><strong>非对称加密</strong>：有一对密钥，公钥随便发，私钥自己留着。公钥加密只有私钥能解，私钥签名公钥能验。慢，但不需要提前共享密钥。</p><p>实际工程里都是混合用：非对称加密交换密钥，对称加密传数据。</p><h2 id="签名的流程" tabindex="-1">签名的流程 <a class="header-anchor" href="#签名的流程" aria-label="Permalink to &quot;签名的流程&quot;">​</a></h2><ol><li>发送方用私钥对数据做签名</li><li>数据 + 签名一起发给接收方</li><li>接收方用发送方的公钥验证签名</li><li>匹配则说明数据没被改过，且确实是发送方发的</li></ol><p>关键点：私钥绝对不能泄露，公钥分发时要防伪造（通常靠证书体系）。</p><h2 id="在固件更新中的应用" tabindex="-1">在固件更新中的应用 <a class="header-anchor" href="#在固件更新中的应用" aria-label="Permalink to &quot;在固件更新中的应用&quot;">​</a></h2><p>我们的固件更新方案分两层：</p><ul><li><strong>签名</strong>：对固件包做数字签名，确保固件来源可信、未被篡改（满足法规要求）</li><li><strong>加密</strong>：对 swu 文件做对称加密，防止固件被提取和逆向</li><li><strong>飞控保护</strong>：使用飞控预置的签名算法做二次校验</li></ul>',16)])])}const _=t(l,[["render",s]]);export{u as __pageData,_ as default};
